// Turns a WhatsApp Cloud API webhook into one item per customer message.
// Status updates (sent/delivered/read) are dropped. No items = workflow stops.
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || {};
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const v = change.value || {};
      if (!Array.isArray(v.messages)) continue; // statuses, errors, etc.
      const contacts = v.contacts || [];
      for (const m of v.messages) {
        const c = contacts.find(x => x.wa_id === m.from) || contacts[0] || {};
        let text = null, media_id = null, mime_type = null, caption = null;
        switch (m.type) {
          case 'text': text = m.text?.body ?? null; break;
          case 'audio': media_id = m.audio?.id; mime_type = m.audio?.mime_type; break;
          case 'image': media_id = m.image?.id; mime_type = m.image?.mime_type; caption = m.image?.caption ?? null; break;
          case 'button': text = m.button?.text ?? null; break;
          case 'interactive': text = m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title ?? null; break;
        }
        out.push({ json: {
          phone_number_id: v.metadata?.phone_number_id,
          display_phone_number: v.metadata?.display_phone_number,
          wa_id: m.from,
          profile_name: c.profile?.name ?? null,
          message_id: m.id,
          type: m.type,
          text, media_id, mime_type, caption,
          is_voice_note: m.audio?.voice ?? null,
          timestamp: new Date(Number(m.timestamp) * 1000).toISOString(),
        }});
      }
    }
  }
}
return out;

// Match incoming WhatsApp number to a client row (multi-client routing)
const m = $('Parse Webhook').first().json;
const rows = $input.all().map(i => i.json);
const c = rows.find(r => String(r.phone_number_id).trim() === String(m.phone_number_id).trim());
if (!c || String(c.active).toUpperCase() === 'FALSE') return []; // unknown or inactive client -> stop
const text_b64 = Buffer.from(String(m.text || ''), 'utf8').toString('base64');
return [{ json: { ...c, ...m, client_id: c.client_id, text_b64 } }];

