// owner command (#...) -> 0 | paused chat -> 1 | normal AI -> 2
const c = $('Client Config').first().json;
const p = $input.first().json.paused;
const paused = p === true || p === 't' || p === 'true';
const digits = s => String(s || '').replace(/\D/g, '');
const owner = digits(c.owner_whatsapp);
const txt = String(c.text || '').trim();
const isOwnerCmd = !!owner && digits(c.wa_id) === owner && c.type === 'text' && txt.startsWith('#');
return [{ json: Object.assign({}, c, { paused, route_index: isOwnerCmd ? 0 : ((paused && digits(c.wa_id) !== owner) ? 1 : 2) }) }];

const c = $input.first().json;
const raw = String(c.text || '').trim();
const m = raw.match(/^#\s*(\w+)\s*([\s\S]*)$/);
const cmd = m ? m[1].toLowerCase() : 'help';
const rest = m ? m[2].trim() : '';
const normNum = s => { let d = String(s || '').replace(/\D/g, ''); if (d.startsWith('00')) d = d.slice(2); if (d.startsWith('0')) d = '92' + d.slice(1); return d; };
const first = rest.split(/\s+/)[0] || '';
const target = first.replace(/\D/g, '').length >= 7 ? normNum(first) : '';
const after = target ? rest.slice(first.length).trim() : rest;
let hours = 24;
if (cmd === 'off' && /^\d{1,3}$/.test(after)) hours = Math.min(168, Math.max(1, Number(after)));
const PAUSE = "INSERT INTO handoff_flags (client_id, wa_id, active, reason, created_at, expires_at) VALUES ($1, $2, true, 'Paused by owner', now(), now() + make_interval(hours => $3::int)) ON CONFLICT (client_id, wa_id) DO UPDATE SET active = true, reason = 'Paused by owner', created_at = now(), expires_at = now() + make_interval(hours => $3::int) RETURNING wa_id;";
let sql;
if ((cmd === 'off' || cmd === 'reply' || cmd === 'r') && target) sql = PAUSE;
else if (cmd === 'on' && target) sql = "UPDATE handoff_flags SET active = false WHERE client_id = $1 AND wa_id = $2 AND $3::int > 0 RETURNING wa_id;";
else if (cmd === 'on') sql = "UPDATE handoff_flags SET active = false WHERE client_id = $1 AND active AND expires_at > now() AND $2::text IS NOT NULL AND $3::int > 0 AND (SELECT count(*) FROM handoff_flags WHERE client_id = $1 AND active AND expires_at > now()) = 1 RETURNING wa_id;";
